import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(arr):
    if not arr or arr[0] == 'n':
        return None
    root = T(int(arr[0]))
    q = deque([root])
    i = 1
    while q and i < len(arr):
        node = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            node.l = T(int(arr[i]))
            q.append(node.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            node.r = T(int(arr[i]))
            q.append(node.r)
        i += 1
    return root

def zigzag_brute(root):
    if root is None:
        return []
    res = []
    q = deque([root])
    depth = 0
    while q:
        size = len(q)
        level = []
        for _ in range(size):
            node = q.popleft()
            level.append(node.v)
            if node.l:
                q.append(node.l)
            if node.r:
                q.append(node.r)
        if depth % 2 == 1:
            level.reverse()
        res.append(level)
        depth += 1
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    root = build(data[1:1 + n])
    for level in zigzag_brute(root):
        print(' '.join(map(str, level)))

